 84	// ---------------------------------------------------------------------------
 85	// Named-options interface
 86	// ---------------------------------------------------------------------------
 87	
 88	export interface ConfigRoutesOptions {
 89	    router: Router;
 90	    appConfig: AppConfig;
 91	    /** Optional absolute path to `config.json`. Defaults to the tool-root `config.json`. */
 92	    configPath?: string;
 93	    /** Optional `PollingManager`. When provided, PUT /api/config/polling restarts the loop. */
 94	    pollingManager?: PollingManager;
 95	}
 96	
 97	/**
 98	 * Registers REST endpoints for managing application configuration in
 99	 * `config.json`.
100	 *

101	 * **Credentials endpoints:**
102	 *
103	 * | Method | Path                              | Description               |
104	 * |--------|-----------------------------------|---------------------------|
105	 * | GET    | /api/config/credentials           | List credentials (masked) |
106	 * | PUT    | /api/config/credentials           | Add / update an entry     |
107	 * | DELETE | /api/config/credentials/:id       | Remove an entry           |
108	 *
109	 * **Polling endpoints:**
110	 *
111	 * | Method | Path                    | Description                                          |
112	 * |--------|-------------------------|------------------------------------------------------|
113	 * | GET    | /api/config/polling     | Return current `gitPollingIntervalSeconds`           |
114	 * | PUT    | /api/config/polling     | Update the polling interval (min 10 s, max 86400 s)  |
115	 *
116	 * **Webserver URL endpoints:**
117	 *
118	 * | Method | Path                         | Description                              |
119	 * |--------|------------------------------|------------------------------------------|
120	 * | GET    | /api/config/webserver-url    | Return current `webserverUrl` (or null)  |
121	 * | PUT    | /api/config/webserver-url    | Update the webserver URL                 |
122	 *
123	 * **Notes display endpoints:**
124	 *
125	 * | Method | Path                          | Description                                                                                                         |
126	 * |--------|-------------------------------|---------------------------------------------------------------------------------------------------------------------|
127	 * | GET    | /api/config/notes-display     | Return current `notesCardHeight` and `notesColumns`                                                                 |
128	 * | PUT    | /api/config/notes-display     | Update notes display settings (partial updates — all fields optional). Fields: `notesCardHeight` ∈ [120, 800] (integer px), `notesColumns` ∈ [1, 6] (integer) |
129	 *
130	 * Changes take effect immediately (the in-memory `appConfig` is mutated) and
131	 * are persisted to `config.json` via `saveConfigField()`.
132	 *
133	 * **Security:** tokens are never returned in full — only the last 4 characters
134	 * are exposed. The `host` field is validated against an injection-safe pattern.
135	 *
136	 * @param options - Named-options bag: `router`, `appConfig`, optional
137	 *   `configPath` (defaults to tool-root `config.json`), optional
138	 *   `pollingManager` (restarts polling loop when present).
139	 */
140	export function registerConfigRoutes(options: ConfigRoutesOptions): void {
141	    const { router, appConfig, configPath, pollingManager } = options;
142	    // ------------------------------------------------------------------
143	    // GET /api/config/credentials — list all (tokens masked)
144	    // Returns GitCredentialEntry[] with tokens masked.
145	    // ------------------------------------------------------------------
146	    router.get('/api/config/credentials', (
147	        _req: IncomingMessage,
148	        res: ServerResponse,
149	        _params: Record<string, string>,
150	    ): void => {
151	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
152	    });
153	
154	    // ------------------------------------------------------------------
155	    // PUT /api/config/credentials — add or update a single entry
156	    //
157	    // Request body: { id?: string, label: string, host: string, token: string }
158	    //
159	    // - When `id` is omitted: auto-generates a kebab-case ID from `label`,
160	    //   appending a numeric suffix (-2, -3, …) if needed to avoid collisions.
161	    //   Always creates a new entry.
162	    // - When `id` is provided and matches an existing entry: upserts (replaces)
163	    //   the existing entry in-place.
164	    // - When `id` is provided and does NOT match any existing entry: creates a
165	    //   new entry with the given ID (after checking the ID is not already taken).
166	    //
167	    // Returns 400 when the resulting ID would collide with an existing entry
168	    // that is NOT the one being updated (duplicate-ID rejection).
169	    // ------------------------------------------------------------------
170	    router.put('/api/config/credentials', async (
171	        req: IncomingMessage,
172	        res: ServerResponse,
173	        _params: Record<string, string>,
174	    ): Promise<void> => {
175	        let body: unknown;
176	        try {
177	            body = await parseJsonBody(req);
178	        } catch (err) {
179	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
180	            return;
181	        }
182	
183	        if (!isPlainObject(body)) {
184	            sendError(res, 400, 'Request body must be a JSON object.');
185	            return;
186	        }
187	
188	        const { id, label, host, token } = body as {
189	            id?: unknown;
190	            label?: unknown;
191	            host?: unknown;
192	            token?: unknown;
193	        };
194	
195	        // Validate required string fields.
196	        if (typeof label !== 'string' || label.trim() === '') {
197	            sendError(res, 400, 'Missing or invalid field "label": must be a non-empty string.');
198	            return;
199	        }
200	        if (typeof host !== 'string' || host.trim() === '') {
201	            sendError(res, 400, 'Missing or invalid field "host": must be a non-empty string.');
202	            return;
203	        }
204	        if (typeof token !== 'string' || token.trim() === '') {
205	            sendError(res, 400, 'Missing or invalid field "token": must be a non-empty string.');
206	            return;
207	        }
208	
209	        // Validate optional `id` field when provided.
210	        if (id !== undefined && (typeof id !== 'string' || id.trim() === '')) {
211	            sendError(res, 400, 'Field "id", when provided, must be a non-empty string.');
212	            return;
213	        }
214	
215	        const cleanLabel = label.trim();
216	        const cleanHost = host.trim();
217	        const cleanToken = token.trim();
218	
219	        const existingCredentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
220	
221	        if (id !== undefined) {
222	            // --- Upsert path: id is explicitly provided ---
223	            const cleanId = (id as string).trim();
224	            const existingIndex = existingCredentials.findIndex((e) => e.id === cleanId);
225	
226	            if (existingIndex === -1) {
227	                // New entry with an explicit ID — no existing entry matches, so create.
228	                const updated = [
229	                    ...existingCredentials,
230	                    { id: cleanId, label: cleanLabel, host: cleanHost, token: cleanToken },
231	                ];
232	                appConfig.gitCredentials = updated;
233	            } else {
234	                // Replace the existing entry at the same position.
235	                const updated = [...existingCredentials];
236	                updated[existingIndex] = { id: cleanId, label: cleanLabel, host: cleanHost, token: cleanToken };
237	                appConfig.gitCredentials = updated;
238	            }
239	        } else {
240	            // --- Create path: no id provided — auto-generate from label ---
241	            const existingIds = new Set(existingCredentials.map((e) => e.id));
242	            const newId = generateUniqueId(cleanLabel, existingIds);
243	            appConfig.gitCredentials = [
244	                ...existingCredentials,
245	                { id: newId, label: cleanLabel, host: cleanHost, token: cleanToken },
246	            ];
247	        }
248	
249	        // Persist to disk.
250	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
251	
252	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
253	    });
254	
255	    // ------------------------------------------------------------------
256	    // DELETE /api/config/credentials/:id — remove a single entry by id
257	    // Sync handler (no request body to parse — unlike the async PUT above).
258	    // ------------------------------------------------------------------
259	    router.delete('/api/config/credentials/:id', (
260	        _req: IncomingMessage,
261	        res: ServerResponse,
262	        params: Record<string, string>,
263	    ): void => {
264	        let credId: string;
265	        try {
266	            credId = decodeURIComponent(params['id']);
267	        } catch {
268	            sendError(res, 400, 'Malformed id parameter.');
269	            return;
270	        }
271	
272	        const existing = appConfig.gitCredentials ?? [];
273	        const idx = existing.findIndex((e) => e.id === credId);
274	
275	        if (idx === -1) {
276	            sendError(res, 404, `No credential entry found with id "${credId}".`);
277	            return;
278	        }
279	
280	        const updated = existing.filter((_, i) => i !== idx);
281	
282	        // When the array is empty, remove the field entirely.
283	        appConfig.gitCredentials = updated.length > 0 ? updated : undefined;
284	
285	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
286	
287	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
288	    });
289	
290	    // ------------------------------------------------------------------
291	    // GET /api/config/polling — return the current polling interval
292	    // ------------------------------------------------------------------
293	    router.get('/api/config/polling', (
294	        _req: IncomingMessage,
295	        res: ServerResponse,
296	        _params: Record<string, string>,
297	    ): void => {
298	        sendJson(res, 200, {
299	            gitPollingIntervalSeconds: appConfig.gitPollingIntervalSeconds,
300	        });

